#!/usr/bin/env node
/**
 * Every `router.push` target is a route that exists.
 *
 * ## The gap this fills
 *
 * `router.push('/palettes')` is a **string**. It compiles whether or not the route exists,
 * `lint` sees a call with an argument, and the failure is a dead button on a screen nobody opened
 * this week. expo-router can generate typed routes into `.expo/types/router.d.ts`, but that file
 * is generated by the dev server rather than by the build, so on a clean checkout — which is what
 * CI is — the types are absent and the strings are unchecked again.
 *
 * F-145 moved sixteen routes into a `(tabs)` group and rewrote thirteen push targets. Nothing in
 * the repository could have told the difference between doing that correctly and doing it
 * almost correctly [[a-gate-must-model-what-renders-not-what-is-physically-correct]].
 *
 * ## How a target is resolved
 *
 * expo-router's rules, as far as they are needed here:
 *
 * - A **group** — a path segment in parentheses — does not appear in the URL. `(tabs)/atlas` is
 *   reachable at `/atlas`.
 * - `index.tsx` is its directory.
 * - `[slug].tsx` matches one segment; a template literal in the source becomes a wildcard.
 * - `_layout.tsx` is not a route.
 *
 * ```
 * node scripts/verify-route-targets.mjs
 * node scripts/verify-route-targets.mjs --prove
 * ```
 */

import { readdirSync, readFileSync, statSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const APP = join(ROOT, 'apps/mobile/app');
const SCAN = [join(ROOT, 'apps/mobile/app'), join(ROOT, 'apps/mobile/src')];

const GREEN = '\x1b[32m',
  RED = '\x1b[31m',
  DIM = '\x1b[2m',
  BOLD = '\x1b[1m',
  OFF = '\x1b[0m';

/**
 * Every source file under a path.
 *
 * **A single FILE is accepted as well as a directory**, so `targets([file])` works. That is what
 * `verify-reachability.mjs` needs to attribute navigation to the route that can reach it — it
 * walks one module at a time — and the alternative was a second copy of the target scanner,
 * which is the thing this repository refuses on principle.
 */
function walk(dir, out = []) {
  if (!statSync(dir).isDirectory()) {
    if (/\.tsx?$/u.test(dir)) out.push(dir);
    return out;
  }
  for (const entry of readdirSync(dir)) {
    const path = join(dir, entry);
    if (statSync(path).isDirectory()) walk(path, out);
    else if (/\.tsx?$/.test(path)) out.push(path);
  }
  return out;
}

/** Every URL the route tree serves, as a regular expression each. */
export function routePatterns(appDir = APP) {
  const patterns = [];
  for (const file of walk(appDir)) {
    const rel = relative(appDir, file)
      .replaceAll('\\', '/')
      .replace(/\.tsx?$/, '');
    const base = rel.split('/').pop();
    if (base === '_layout') continue;

    const url =
      '/' +
      rel
        .split('/')
        .filter((s) => !/^\(.*\)$/.test(s)) // a group is not part of the URL
        .filter((s, i, a) => !(s === 'index' && i === a.length - 1))
        .join('/');

    patterns.push({
      file: rel,
      url,
      test: new RegExp(
        '^' +
          url
            .split('/')
            .map((s) => (/^\[.+\]$/.test(s) ? '[^/]+' : s.replace(/[.*+?^${}()|[\]\\]/gu, '\\$&')))
            .join('/') +
          '/?$',
        'u',
      ),
    });
  }
  return patterns;
}

/** Every navigation target in the source, with where it was written. */
export function targets(dirs = SCAN) {
  const found = [];
  for (const dir of dirs)
    for (const file of walk(dir)) {
      const source = readFileSync(file, 'utf8');
      source.split('\n').forEach((line, index) => {
        /*
         * AN HREF RETURNED BY AN ARROW IS STILL A NAVIGATION TARGET (F-178).
         *
         * This scan matched `router.push('…')` and nothing else, which was true of every
         * navigation in the product until F-178 moved the Lens's four exits into a table of
         * `() => '/profile'` rows. **The gate then found 11 targets where it had found 15, and
         * still printed "Every target resolves."**
         *
         * Nothing went red. Four routes simply stopped being checked — and a check that gets
         * QUIETER is worse than one that fails, because a failure is visible and this was not
         * [[a-truncated-report-reads-exactly-like-a-passing-one]].
         *
         * Deliberately narrow: the arrow, then a quote, then a slash. A string beginning with
         * `/` inside `app/` or `src/` is a route or it is nothing, and widening this to every
         * such literal would start reporting file paths and regular expressions.
         */
        for (const m of line.matchAll(/=>\s*[`'"](\/[^`'"]*)/gu)) {
          found.push({
            file: relative(ROOT, file).replaceAll('\\', '/'),
            line: index + 1,
            target: m[1].replace(/\$\{[^}]*\}/gu, 'PARAM'),
          });
        }
        for (const m of line.matchAll(/router\.(?:push|replace|navigate)\(\s*[`'"]([^`'"]+)/gu)) {
          // A template literal's `${…}` is a value known only at runtime. It becomes a wildcard,
          // which is the honest reading: the check can say the SHAPE exists, not that the id does.
          const target = m[1].replace(/\$\{[^}]*\}/gu, 'PARAM');
          found.push({
            file: relative(ROOT, file).replaceAll('\\', '/'),
            line: index + 1,
            target,
          });
        }
      });
    }
  return found;
}

/**
 * The PATH a target names — the query dropped.
 *
 * Exported so the orphan scan and the resolution check ask the same question. Two callers
 * normalising separately is how they end up disagreeing about what a route is.
 */
export function pathOf(target) {
  return target.replaceAll('PARAM', 'x').split('?')[0] ?? '';
}

export function run(appDir = APP, dirs = SCAN) {
  const patterns = routePatterns(appDir);
  const problems = [];
  const checked = targets(dirs);

  for (const t of checked) {
    /*
     * THE QUERY IS STRIPPED BEFORE MATCHING, and it was not (found in F-199).
     *
     * A query string is not part of a path. Leaving it on had two effects, both bad and both
     * silent: `/atlas/compare?a=x` matched `/atlas/[slug]` — because `[^/]+` swallows
     * `compare?a=x` whole — so the gate reported a target as resolving against a route that
     * would never serve it; and a legitimate query on a STATIC route failed, because no pattern
     * ends in one.
     *
     * The first is the one that matters: a check that resolves against the wrong route is
     * worse than one that fails, because it reports success
     * [[a-check-that-gets-quieter-is-worse-than-one-that-fails]].
     */
    const resolved = pathOf(t.target);
    if (!patterns.some((p) => p.test.test(resolved)))
      problems.push(
        `${t.file}:${String(t.line)} navigates to "${t.target}", which no route serves. ` +
          'A push target is a string: it compiles, it lints, and it fails as a dead control on a ' +
          'screen somebody opens later.',
      );
  }
  return { problems, routes: patterns.length, checked: checked.length };
}

/*
 * ONLY WHEN THIS FILE IS THE ENTRY POINT.
 *
 * It ran on IMPORT before, which nothing noticed while nothing imported it. F-179's
 * reachability gate is the converse of this one and reuses `routePatterns` and `targets`
 * rather than re-deriving them — and importing them printed a full route-target report above
 * the reachability report, on every run.
 *
 * That is the harmless half. The harmful half is that a module which RUNS when imported cannot
 * be reused at all without its side effect, so the next check that needs the route model would
 * have copied it instead — and two checks disagreeing about what a route is would each be right
 * about their own model and wrong about the product.
 */
if (process.argv[1] !== undefined && fileURLToPath(import.meta.url) === resolve(process.argv[1])) {
  if (process.argv.includes('--prove')) prove();
  else main();
}

function main() {
  console.log(`\n${BOLD}Irodora — route targets${OFF}\n`);
  const { problems, routes, checked } = run();
  console.log(
    `  ${DIM}${String(checked)} navigation target(s) against ${String(routes)} route(s)${OFF}`,
  );
  if (problems.length > 0) {
    console.log(`\n${RED}${BOLD}${String(problems.length)} problem(s).${OFF}\n`);
    for (const p of problems) console.log(`  ${RED}✗${OFF} ${p}\n`);
    process.exit(1);
  }
  console.log(`\n${GREEN}${BOLD}Every target resolves.${OFF}\n`);
}

/** Watch it fail. The tree is read; nothing is written. */
function prove() {
  console.log(`\n${BOLD}Irodora — route target proof${OFF}\n`);
  const problems = [];
  const say = (ok, name, detail) => {
    if (!ok) problems.push(name);
    console.log(`  ${ok ? GREEN + '✓' : RED + '✗'}${OFF} ${name} ${DIM}${detail}${OFF}`);
  };

  say(run().problems.length === 0, 'baseline clean', '(asserted first, or a plant proves nothing)');

  const patterns = routePatterns();
  const urls = patterns.map((p) => p.url);
  say(
    urls.includes('/atlas') && urls.includes('/lens'),
    'a group is not part of the URL',
    '(tabs)/atlas/index.tsx serves /atlas',
  );
  say(
    !urls.some((u) => u.includes('_layout')),
    'a layout is not a route',
    '_layout.tsx serves nothing',
  );
  say(
    patterns.some((p) => p.test.test('/atlas/ai-nezumi')),
    'a dynamic segment matches one segment',
    '[slug].tsx',
  );
  say(
    !patterns.some((p) => p.test.test('/atlas/ai-nezumi/extra')),
    'and it does NOT match two — the decoy',
    'without this the pattern could be matching everything',
  );
  say(
    run(APP, []).problems.length === 0 && run(APP, []).checked === 0,
    'scanning nothing finds nothing',
    'zero targets is zero problems, not a silent pass over a real one',
  );

  // A target that no route serves must be reported. Planted in memory over the real tree.
  const planted = [{ file: 'planted.tsx', line: 1, target: '/atlas/nope/deeper' }];
  const unmatched = planted.filter(
    (t) => !routePatterns().some((p) => p.test.test(pathOf(t.target))),
  );
  say(unmatched.length === 1, 'an unknown target is reported', '/atlas/nope/deeper');

  if (problems.length > 0) {
    console.log(`\n${RED}${BOLD}${String(problems.length)} case(s) did not discriminate.${OFF}\n`);
    process.exit(1);
  }
  console.log(`\n${GREEN}${BOLD}The route check discriminates.${OFF}\n`);
}
